<?php require_once __DIR__.'/includes/bootstrap.php'; $pageTitle='Weather demo | StudentHub'; include __DIR__.'/includes/header.php'; ?>
<main id="main-content"><section class="page-title"><h1>Weather demo</h1><p>Small optional JavaScript API exercise.</p></section><section class="form-card"><h2>Check current weather</h2><p class="hint">This demo uses Open-Meteo geocoding and weather APIs; internet access is required.</p><div class="field"><label for="city">City</label><input id="city" value="Anand" placeholder="Enter a city"></div><button id="weatherButton" class="btn">Get weather</button><p id="weather" role="status" aria-live="polite"></p></section></main>
<script>
document.getElementById('weatherButton').addEventListener('click',async()=>{const out=document.getElementById('weather'),city=document.getElementById('city').value.trim();if(!city){out.textContent='Enter a city.';return}out.textContent='Loading…';try{const g=await fetch('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(city)+'&count=1');const gd=await g.json();if(!gd.results?.length)throw Error('City not found.');const p=gd.results[0];const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${p.latitude}&longitude=${p.longitude}&current=temperature_2m,relative_humidity_2m,wind_speed_10m`);const d=await r.json();out.textContent=`${p.name}: ${d.current.temperature_2m}°C · Humidity ${d.current.relative_humidity_2m}% · Wind ${d.current.wind_speed_10m} km/h`;}catch(e){out.textContent='Weather is unavailable right now. Check your connection and try again.'}});
</script><?php include __DIR__.'/includes/footer.php'; ?>
